export async function listProjects(
  actor: Actor,
  input: ListProjectsInput,
): Promise<Page<ProjectWithStats>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:read", orgResource(input.orgId));

  const projects = await projectRepo.listProjectsForVisibility(input.orgId);
  const visibleProjectIds = await Promise.all(
    projects.map(async (project) =>
      (await canViewProject(actor, project)) ? project.id : null,
    ),
  );
  const page = await projectRepo.listProjects(
    input,
    visibleProjectIds.filter((id): id is ProjectId => id !== null),
  );

  const items = await Promise.all(
    page.items.map(async (project) => ({
      project,
      stats: await projectRepo.getProjectStats(input.orgId, project.id),
    })),
  );

  return { items, nextCursor: page.nextCursor, total: page.total };
}

/** Whether an actor can see this project and its contents. */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (actor.orgId !== project.orgId) return false;
  if (project.visibility !== "private") return true;
  if (
    actor.isPlatformStaff === true ||
    actor.role === "admin" ||
    actor.role === "owner" ||
    project.leadId === actor.userId
  ) {
    return true;
  }
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/** Hide inaccessible private projects as missing before normal RBAC checks. */
export async function assertProjectVisible(
  actor: Actor,
  project: Project,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", project.id);
  }
}

